// Regenerates tests/fixtures/call_bundle_vectors.json from salt-fe's REAL callCrypto.js, so the SDK's
// callBundle.ts is checked against the implementation the browser runs, not against itself.
//
//   SALT_FE=/path/to/salt-fe node tests/fixtures/gen-call-bundle-fixture.mjs
//
// It writes: three keypairs (a person, a device, and a legacy one still locked under the constant
// passphrase "salt"), an offer signed and encrypted BY salt-fe's signAndEncrypt, and an answer signed and
// encrypted BY the SDK, which salt-fe's decryptAndVerify is asserted to accept before the file is written.
// Run `npm run build` first (it imports ../../dist). The keys are throwaway test keys.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const saltFe = process.env.SALT_FE || "/Users/z1ggy/projects/salt/salt-fe";
const feOpenpgp = path.join(saltFe, "node_modules/openpgp/dist/node/openpgp.mjs");
const feSource = fs.readFileSync(path.join(saltFe, "src/utilities/callCrypto.js"), "utf8").replace("from 'openpgp'", `from '${pathToFileURL(feOpenpgp).href}'`);
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "salt-callcrypto-"));
const feFile = path.join(tmp, "callCrypto.mjs");
fs.writeFileSync(feFile, feSource);
const fe = await import(pathToFileURL(feFile).href);
const openpgp = await import(pathToFileURL(feOpenpgp).href);
const sdk = createRequire(import.meta.url)(path.join(here, "../../dist/index.js"));

async function keypair(name, passphrase) {
  const { privateKey, publicKey } = await openpgp.generateKey({ type: "ecc", curve: "curve25519", userIDs: [{ name }], format: "armored", ...(passphrase ? { passphrase } : {}) });
  return { privateKey, publicKey };
}

const SDP = (fp) => `v=0\r\no=- 4611731400430051336 2 IN IP4 127.0.0.1\r\ns=-\r\nt=0 0\r\na=group:BUNDLE 0 1\r\nm=video 9 UDP/TLS/RTP/SAVPF 102\r\nc=IN IP4 0.0.0.0\r\na=fingerprint:sha-256 ${fp}\r\na=setup:actpass\r\na=mid:0\r\nm=application 9 UDP/DTLS/SCTP webrtc-datachannel\r\nc=IN IP4 0.0.0.0\r\na=fingerprint:sha-256 ${fp}\r\na=mid:1\r\n`;

const person = await keypair("person");
const device = await keypair("device");
const legacy = await keypair("legacy", "salt");

const now = Math.floor(Date.now() / 1000);
const offerSdp = SDP("AB:CD:EF:01:23:45:67:89:AB:CD:EF:01:23:45:67:89:AB:CD:EF:01:23:45:67:89:AB:CD:EF:01:23:45:67:89");
const answerSdp = SDP("11:22:33:44:55:66:77:88:99:00:AA:BB:CC:DD:EE:FF:11:22:33:44:55:66:77:88:99:00:AA:BB:CC:DD:EE:FF");
const offerBundle = { v: 1, call_id: "call-session-1", kind: "watch", sdp: offerSdp, dtls_fingerprints: sdp_fps(offerSdp), ts: now, nonce: "00112233445566778899aabbccddeeff" };
function sdp_fps(sdp) { return fe.parseSdpFingerprints(sdp); }
const answerBundle = sdk.buildCallBundle({ callId: "call-session-1", kind: "watch", sdp: answerSdp, ts: now, nonce: "ffeeddccbbaa99887766554433221100" });

const feOffer = await fe.signAndEncrypt({ bundle: offerBundle, signingPrivateKey: person.privateKey, receiverPublicKey: device.publicKey });
const feLegacyOffer = await fe.signAndEncrypt({ bundle: offerBundle, signingPrivateKey: legacy.privateKey, receiverPublicKey: device.publicKey });
const sdkAnswer = await sdk.signAndEncrypt({ bundle: answerBundle, signingPrivateKey: device.privateKey, receiverPublicKey: person.publicKey });
const sdkLegacyAnswer = await sdk.signAndEncrypt({ bundle: answerBundle, signingPrivateKey: legacy.privateKey, receiverPublicKey: person.publicKey });

// salt-fe must accept what the SDK produced.
for (const [armored, signer] of [[sdkAnswer, device], [sdkLegacyAnswer, legacy]]) {
  const r = await fe.decryptAndVerify({ armored, decryptionPrivateKey: person.privateKey, senderPublicKey: signer.publicKey });
  if (!r.signatureValid || JSON.stringify(r.bundle) !== JSON.stringify(answerBundle)) throw new Error("salt-fe rejected an SDK-signed bundle");
}

fs.writeFileSync(
  path.join(here, "call_bundle_vectors.json"),
  JSON.stringify(
    {
      note: "Generated by gen-call-bundle-fixture.mjs from salt-fe's callCrypto.js. Throwaway keys.",
      keys: { person, device, legacy: { ...legacy, passphrase: "salt" } },
      offer_bundle: offerBundle,
      answer_bundle: answerBundle,
      fe_offer: feOffer,
      fe_legacy_offer: feLegacyOffer,
      sdk_answer: sdkAnswer,
      sdk_legacy_answer: sdkLegacyAnswer,
      offer_sdp: offerSdp,
      answer_sdp: answerSdp,
      fe_parse_offer_fingerprints: fe.parseSdpFingerprints(offerSdp),
      fe_fingerprints_match: fe.fingerprintsMatch(offerBundle.dtls_fingerprints, offerSdp),
    },
    null,
    2
  ) + "\n"
);
console.log("wrote tests/fixtures/call_bundle_vectors.json");
